        ops, _ = self.timeline_ops()
        result = self.traced(self.run_ops(
            ops + [self.eg("f" * 64, 4242, 0, 7)]
        ))
        self.assertEqual(result["events"], [])
        self.assertEqual(result["state"], "INACTIVE")
        self.assertFalse(result["truncated"])

